BEGIN;
CREATE FUNCTION public.creator_program_analytics() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE result jsonb;BEGIN IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=auth.uid() AND role='trainer') OR NOT account_can_act(auth.uid(),false) THEN RAISE EXCEPTION 'Trainer account required';END IF;
 WITH enrollments AS (SELECT user_id,edition_id,program_id FROM program_enrollments UNION SELECT user_id,edition_id,program_id FROM program_subscription_enrollments),
 per_member AS(SELECT n.program_id,n.user_id,n.edition_id,(SELECT count(*) FROM jsonb_path_query(e.document,'$.weeks[*].days[*].workouts[*]'))+jsonb_array_length(coalesce(e.document->'downloads','[]')) total,(SELECT count(*) FROM program_progress g WHERE g.user_id=n.user_id AND g.edition_id=n.edition_id AND g.completed)+(SELECT count(*) FROM program_download_progress g WHERE g.user_id=n.user_id AND g.edition_id=n.edition_id AND g.completed) completed,EXISTS(SELECT 1 FROM program_progress g WHERE g.user_id=n.user_id AND g.edition_id=n.edition_id AND (g.completed OR g.elapsed_seconds>0)) OR EXISTS(SELECT 1 FROM program_download_progress g WHERE g.user_id=n.user_id AND g.edition_id=n.edition_id AND g.completed) started FROM enrollments n JOIN program_editions e ON e.id=n.edition_id JOIN trainer_programs p ON p.id=n.program_id WHERE p.trainer_id=auth.uid())
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'enrollments',(SELECT count(*) FROM per_member n WHERE n.program_id=p.id),'starts',(SELECT count(*) FROM per_member n WHERE n.program_id=p.id AND n.started),'averageProgress',(SELECT coalesce(round(avg(least(completed::numeric/NULLIF(total,0),1)*100)),0) FROM per_member n WHERE n.program_id=p.id),'completionRate',(SELECT coalesce(round(100.0*count(*) FILTER(WHERE n.total>0 AND n.completed>=n.total)/NULLIF(count(*),0)),0) FROM per_member n WHERE n.program_id=p.id),'lessons',(SELECT coalesce(jsonb_agg(jsonb_build_object('title',coalesce(s->>'title','Workout'),'edition',e.version,'completed',(SELECT count(*) FROM program_progress g WHERE g.edition_id=e.id AND g.step_id=(s->>'id')::uuid AND g.completed),'started',(SELECT count(*) FROM program_progress g WHERE g.edition_id=e.id AND g.step_id=(s->>'id')::uuid AND (g.completed OR g.elapsed_seconds>0)))),'[]') FROM program_editions e CROSS JOIN LATERAL jsonb_path_query(e.document,'$.weeks[*].days[*].workouts[*]') s WHERE e.program_id=p.id)) ORDER BY p.created_at DESC),'[]') INTO result FROM trainer_programs p WHERE p.trainer_id=auth.uid() AND p.builder_version=2;RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.creator_program_analytics() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.creator_program_analytics() TO authenticated;
CREATE FUNCTION public.program_milestone_notice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE t uuid;total integer;done integer;BEGIN IF NEW.completed AND (TG_OP='INSERT' OR NOT OLD.completed) THEN SELECT p.trainer_id,(SELECT count(*) FROM jsonb_path_query(e.document,'$.weeks[*].days[*].workouts[*]'))+jsonb_array_length(coalesce(e.document->'downloads','[]')) INTO t,total FROM program_editions e JOIN trainer_programs p ON p.id=e.program_id WHERE e.id=NEW.edition_id;SELECT (SELECT count(*) FROM program_progress WHERE user_id=NEW.user_id AND edition_id=NEW.edition_id AND completed)+(SELECT count(*) FROM program_download_progress WHERE user_id=NEW.user_id AND edition_id=NEW.edition_id AND completed) INTO done;IF done>=total AND total>0 THEN PERFORM creator_notify(t,'program-completed:'||NEW.user_id||':'||NEW.edition_id,'A member completed a program edition. View aggregate progress in Analytics.','/studio?section=analytics');END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER workout_completion_notice AFTER INSERT OR UPDATE OF completed ON public.program_progress FOR EACH ROW EXECUTE FUNCTION public.program_milestone_notice();
CREATE TRIGGER download_completion_notice AFTER INSERT OR UPDATE OF completed ON public.program_download_progress FOR EACH ROW EXECUTE FUNCTION public.program_milestone_notice();
REVOKE ALL ON FUNCTION public.program_milestone_notice() FROM PUBLIC,anon,authenticated;
COMMIT;
